#pragma once
#include <Arduino.h>
#include <Wire.h>
#include <CodeLabRobot.h>
#include <I2CReceiver.h>
#include "QuadMotors.h"
#include "CodeLabV2Scheduler.hpp"

#if !CONFIG_IDF_TARGET_ESP32S3
#error "CodeLabFast4wd requires ESP32-S3."
#endif

namespace codelab { namespace fast4wd {
struct MotorLayout {
  uint8_t wheelAtPort[4] = {0, 1, 2, 3};
  uint8_t reversed = 3;
  uint8_t enabled = 15;
};

class Robot : private robot::MotorInterface {
  enum class Drive { Idle, Ps4, Fixed };
  struct MotorCommand {
    bool active = false;
    float target = 0;
    uint32_t duration = 0, startedAt = 0;
  };
  static constexpr uint8_t ledPin = 47;
  QuadMotors motors_;
  const MotorLayout layout_;
  const float limit_;
  MotorCommand commands_[4];
  float applied_[4] = {};
  bool returning_[4] = {};
  uint32_t lastOutputAt_ = 0;
  robot::MockServo servo_;
  robot::RobotController controller_;
  robot::Ps4ControlMapping controls_;
  ps4i2c::Receiver receiver_;
  bool busReady_ = false, initialized_ = false, blink_ = false;
  bool armAfterClear_ = false, stopRequested_ = false;
  Drive drive_ = Drive::Idle;
  robot::Twist fixed_;
  uint32_t polledAt_ = 0, printedAt_ = 0;
  uint32_t previousButtons_ = 0, pressed_ = 0, released_ = 0;
  bool buttonsLinked_ = false;
  // Blockly policy is selected only by generated programs. Reference clients
  // retain the original controller policy and unchanged physical drivers.
  bool blockly_ = false, ps4Dependent_ = false, motorFault_ = false;
  bool blocklyTicked_ = false, linkSeen_ = false;
  uint32_t blocklyAt_ = 0, motionEpoch_ = 0, observedReport_ = 0;
  uint32_t inputButtons_ = 0x1fcffU; // excludes Options/Share as system controls
  uint8_t inputAxes_ = 7;
  enum class Recovery { NEUTRAL, ACTION, READY } recovery_ = Recovery::NEUTRAL;

  void updateBlocklyLink(uint32_t now) {
    if (!ps4Dependent_) return;
    const auto input = receiver_.snapshot(now);
    if (!busReady_ || !input.connected) {
      if (linkSeen_) { ++motionEpoch_; disable(); }
      linkSeen_ = false;
      recovery_ = Recovery::NEUTRAL;
      return;
    }
    linkSeen_ = true;
    if (receiver_.advances == observedReport_) return;
    observedReport_ = receiver_.advances;
    const int16_t axes[] = {input.lx,input.ly,input.rx,input.ry};
    bool neutral = (input.buttons & inputButtons_) == 0;
    for (unsigned i=0;i<4;++i) if ((inputAxes_ & (1U<<i)) && abs(axes[i]) > 60) neutral = false;
    if (recovery_ == Recovery::NEUTRAL && neutral) recovery_ = Recovery::ACTION;
    else if (recovery_ == Recovery::ACTION && !neutral) recovery_ = Recovery::READY;
  }

  void endBlocklyLoop(uint32_t now) {
    if (!canCommand()) { disable(); return; }
    float mixed[4] = {};
    if (drive_ != Drive::Idle) {
      robot::Twist intent = fixed_;
      if (drive_ == Drive::Ps4) {
        const auto input = receiver_.snapshot(now);
        const auto axis = [](int value) { const float x=value/1000.0f,a=fabsf(x); return a<=0.06f?0.0f:(x<0?-1:1)*(a-0.06f)/0.94f; };
        // The legacy PS4 macro retains its axis convention and turn priority.
        intent = {abs(input.lx)>100?0.0f:axis(input.ly), axis(input.rx), abs(input.lx)>100?axis(input.lx):0.0f};
      }
      if (!robot::MecanumMixer::mix(intent, config(limit_,layout_).mixer, mixed)) { motorFault_=true; disable(); return; }
    }
    bool requested = drive_ != Drive::Idle;
    for (const auto& command:commands_) requested = requested || command.active;
    if (!requested) return; // Boot never permits PWM without a student command.
    if (!motors_.permitted() && !motors_.permit(now)) { motorFault_=true; disable(); return; }
    motors_.renew(now);
    if (!write(mixed)) { motorFault_=true; disable(); }
  }

  static robot::ControlConfig config(float limit, const MotorLayout& layout) {
    robot::ControlConfig c;
    c.mixer.speedLimit = limit;
    c.accelerationPerSecond = 12.0f;
    c.deadzone = 0.06f;
    for (unsigned port = 0; port < 4; ++port) {
      c.mixer.wheelAtOutput[port] = layout.wheelAtPort[port];
      c.mixer.inverted[port] = (layout.reversed & (1U << port)) != 0;
    }
    c.servo.minimum = 45;
    c.servo.maximum = 135;
    c.servo.initial = 90;
    c.servo.rateDegPerSecond = 30;
    return c;
  }

  bool motorEnabled(unsigned port) const { return port < 4 && (layout_.enabled & (1U << port)); }
  bool ready() const override { return motors_.ready(); }
  void disable() override {
    motors_.disable();
    for (unsigned port = 0; port < 4; ++port) {
      commands_[port] = {};
      applied_[port] = 0;
      returning_[port] = false;
    }
  }

  bool write(const float (&mixed)[4]) override {
    const uint32_t now = millis();
    const uint32_t elapsed = now - lastOutputAt_;
    lastOutputAt_ = now;
    const float ramp = 0.012f * (elapsed < 50 ? elapsed : 50);
    float output[4];
    for (unsigned port = 0; port < 4; ++port) {
      auto& command = commands_[port];
      if (command.duration && uint32_t(now - command.startedAt) >= command.duration) {
        command = {true, 0, 0, 0};
      }
      output[port] = mixed[port];
      if (!motorEnabled(port) || (command.active && command.target == 0)) output[port] = 0;
      else if (command.active || returning_[port]) {
        const float target = command.active ? command.target : mixed[port];
        const float delta = target - applied_[port];
        output[port] = fabsf(delta) <= ramp ? target : applied_[port] + robot::clamp(delta, -ramp, ramp);
        if (!command.active && output[port] == target) returning_[port] = false;
      }
    }
    if (!motors_.write(output)) return false;
    for (unsigned port = 0; port < 4; ++port) applied_[port] = output[port];
    return true;
  }

  void sampleButtons(uint32_t now) {
    const auto input = receiver_.snapshot(now);
    pressed_ = released_ = 0;
    if (input.connected && buttonsLinked_) {
      pressed_ = input.buttons & ~previousButtons_;
      released_ = previousButtons_ & ~input.buttons;
    }
    buttonsLinked_ = input.connected;
    previousButtons_ = input.buttons;
  }

  bool canCommand() const {
    if (blockly_) return initialized_ && motors_.ready() && !motorFault_ && !stopRequested_ &&
      (!ps4Dependent_ || (connected() && recovery_ == Recovery::READY));
    return controller_.state() == robot::State::ARMED && motors_.permitted() &&
      connected() && !stopRequested_ && !button(8);
  }

  void poll(uint32_t now) {
    receiver_.watchdog(now);
    if (!busReady_ || uint32_t(now - polledAt_) < 6) return;
    polledAt_ = now;
    const size_t count = Wire.requestFrom(uint8_t(0x30), ps4i2c::frameSize);
    uint8_t bytes[ps4i2c::frameSize];
    size_t received = 0;
    while (Wire.available() && received < sizeof(bytes)) bytes[received++] = uint8_t(Wire.read());
    receiver_.ingest(bytes, count == sizeof(bytes) ? received : 0, millis());
  }

  static const char* stateName(robot::State state) {
    if (state == robot::State::ARMED) return "ARMED";
    if (state == robot::State::FAULT) return "FAULT";
    return "DISARMED";
  }

 public:
  void configureBlockly(bool ps4Dependent, uint32_t buttons = 0x1fcffU, uint8_t axes = 7) {
    blockly_ = true; ps4Dependent_ = ps4Dependent;
    inputButtons_ = buttons; inputAxes_ = axes;
  }
  void requirePs4() {
    if (!ps4Dependent_) { ps4Dependent_=true; recovery_=Recovery::NEUTRAL; ++motionEpoch_; disable(); }
  }
  bool motionAllowed() const { return canCommand(); }
  uint32_t motionEpoch() const { return motionEpoch_; }
  void haltMotorOutputs() { if (blockly_) { disable(); drive_=Drive::Idle; fixed_={}; } stopRequested_=true; }
  explicit Robot(uint8_t speedPercent = 100, MotorLayout layout = {}) :
    layout_(layout), limit_(robot::clamp(speedPercent, 1, 100) / 100.0f),
    controller_(*this, servo_, config(limit_, layout_)) {}
  Robot(const Robot&) = delete;
  Robot& operator=(const Robot&) = delete;

  void begin(bool blinkOnLoss) {
    if (initialized_) return;
    blink_ = blinkOnLoss;
    if (blink_) {
      pinMode(ledPin, OUTPUT);
      digitalWrite(ledPin, LOW);
    }
    delay(300);
    busReady_ = Wire.begin(8, 9, uint32_t(100000));
    Wire.setTimeOut(20);
    initialized_ = true;
    const bool motorReady = motors_.begin();
    if (blockly_) Serial.printf("Blockly I2C=%u MCPWM=%u. Program starts at boot.\n", unsigned(busReady_), unsigned(motorReady));
    else Serial.printf("4WD I2C=%u MCPWM=%u. Options=ARM, Share=STOP.\n", unsigned(busReady_), unsigned(motorReady));
  }

  void beginLoop() {
    drive_ = Drive::Idle;
    stopRequested_ = false;
    if (!initialized_) return;
    const uint32_t now = millis();
    if (blockly_ && blocklyTicked_ && uint32_t(now-blocklyAt_) > 250) { motorFault_=true; disable(); }
    motors_.expire(now);
    poll(now);
    sampleButtons(millis());
    if (blockly_) updateBlocklyLink(millis());
  }

  bool connected() const { return busReady_ && receiver_.snapshot(millis()).connected; }
  bool controllerArmed() const { return controller_.state() == robot::State::ARMED; }
  float axis(unsigned index) const {
    const auto input = receiver_.snapshot(millis());
    const int16_t axes[] = {input.lx, input.ly, input.rx, input.ry};
    return index < 4 ? axes[index] / 10.0f : 0;
  }
  bool button(unsigned bit) const {
    return bit < 17 && (receiver_.snapshot(millis()).buttons & (1UL << bit));
  }
  bool buttonEdge(unsigned bit, bool press) const {
    return connected() && bit < 17 && ((press ? pressed_ : released_) & (1UL << bit));
  }
  void driveFromPs4() { drive_ = Drive::Ps4; }
  void move(float forward, float left, float counterclockwise) {
    if (!isfinite(forward) || !isfinite(left) || !isfinite(counterclockwise)) { stop(); return; }
    drive_ = Drive::Fixed;
    fixed_ = {forward, left, counterclockwise};
  }
  void movePercent(float forward, float left, float counterclockwise) {
    move(forward / 100.0f, left / 100.0f, counterclockwise / 100.0f);
  }
  void stop() { haltMotorOutputs(); }

  bool spin(unsigned port, float percent, bool reverse) {
    if (!motorEnabled(port) || !canCommand()) return false;
    if (!isfinite(percent)) { stop(); return false; }
    const float duty = robot::clamp(percent, 0, limit_ * 100) / 100.0f;
    const bool inverted = (layout_.reversed & (1U << port)) != 0;
    if (blockly_ && !motors_.permitted() && !motors_.permit(millis())) { motorFault_=true; disable(); return false; }
    commands_[port] = {true, inverted != reverse ? -duty : duty, 0, 0};
    return true;
  }
  bool spinFor(unsigned port, float percent, bool reverse, uint32_t duration) {
    if (duration < 1 || duration > 5000 || !spin(port, percent, reverse)) return false;
    commands_[port].duration = duration;
    commands_[port].startedAt = millis();
    return true;
  }
  void stopMotor(unsigned port) {
    if (motorEnabled(port) && canCommand()) commands_[port] = {true, 0, 0, 0};
  }
  void releaseMotor(unsigned port) {
    if (motorEnabled(port) && canCommand() && commands_[port].active) {
      commands_[port] = {};
      returning_[port] = true;
    }
  }
  float motorPwm(unsigned port) const {
    if (!motorEnabled(port) || !motors_.permitted()) return 0;
    const int duty[] = {motors_.m1FI() - motors_.m1BI(), motors_.m2FI() - motors_.m2BI(),
      motors_.m3FI() - motors_.m3BI(), motors_.m4FI() - motors_.m4BI()};
    return duty[port] * (100.0f / 255) * ((layout_.reversed & (1U << port)) ? -1 : 1);
  }
  bool waitForMotor(unsigned port) {
    if (!motorEnabled(port) || !commands_[port].duration) return false;
    endLoop();
    while (canCommand() && commands_[port].duration) {
      beginLoop();
      endLoop();
    }
    const bool completed = canCommand();
    // Freshness can expire during endLoop's yield, before the next tick.
    if (!completed && controller_.state() == robot::State::ARMED) endLoop();
    pressed_ = released_ = 0;
    return completed;
  }

  void endLoop() {
    if (initialized_) {
      const uint32_t now = millis();
      receiver_.watchdog(now);
      auto input = receiver_.snapshot(now);
      const bool fresh = busReady_ && input.connected;
      if (blink_) digitalWrite(ledPin, fresh || ((now / 250U) % 2U == 0U) ? HIGH : LOW);
      if (blockly_) {
        updateBlocklyLink(now);
        endBlocklyLoop(now);
        blocklyAt_=now; blocklyTicked_=true;
        delay(2);
        return;
      }

      // Preserve fast100's left-stick turn priority over forward motion.
      const int16_t turn = input.lx;
      input.lx = input.rx;
      input.rx = 0;
      input.ry = 0;
      if (abs(turn) > 100) {
        input.rx = turn;
        input.ly = 0;
      }

      auto request = controls_.requests(input, now);
      request.disarm = request.disarm || stopRequested_ || button(8);
      if (request.disarm) request.arm = request.clearFault = false;
      const bool neutral = abs(input.lx) <= 80 && abs(input.ly) <= 80 && abs(input.rx) <= 80 &&
        (input.buttons & ((1UL << 13) | (1UL << 14))) == 0;
      if (armAfterClear_ && controller_.state() == robot::State::DISARMED && fresh && neutral && !request.disarm) {
        request.arm = true;
      }
      const bool clearLinkWithOptions = request.arm && controller_.state() == robot::State::FAULT &&
        controller_.fault() == robot::Fault::LINK && fresh && neutral && motors_.ready();
      if (clearLinkWithOptions) {
        request.arm = false;
        request.clearFault = true;
      }

      if (!busReady_ || receiver_.timedOut(now)) controller_.linkFault();
      const auto previous = controller_.state();
      if (previous == robot::State::ARMED && drive_ != Drive::Ps4) {
        const robot::Twist intent = drive_ == Drive::Fixed ? fixed_ : robot::Twist{};
        input.ly = int16_t(robot::clamp(intent.vx, -1, 1) * 1000);
        input.lx = int16_t(robot::clamp(intent.vy, -1, 1) * 1000);
        input.rx = int16_t(robot::clamp(intent.omega, -1, 1) * 1000);
      }
      controller_.tick(input, now, request, false);
      armAfterClear_ = clearLinkWithOptions && controller_.state() == robot::State::DISARMED;
      if (previous != robot::State::ARMED && controller_.state() == robot::State::ARMED &&
          (!fresh || !motors_.permit(now))) controller_.linkFault();
      if (previous != robot::State::ARMED) lastOutputAt_ = now;
      if (controller_.state() == robot::State::ARMED && fresh) motors_.renew(now);

      if (uint32_t(now - printedAt_) >= 1000) {
        printedAt_ = now;
        Serial.printf("4WD connected=%u state=%s fault=%u EN=%u fresh=%lu errors=%lu\n",
          unsigned(fresh), stateName(controller_.state()), unsigned(controller_.fault()), unsigned(motors_.permitted()),
          (unsigned long)receiver_.advances, (unsigned long)receiver_.errors);
      }
    }
    delay(2);
  }
};
} }

#pragma once

#include "Fast4wdSchedulerGate.h"
#include "NewmaniaSupport.h"
#include <cmath>
#include <cstdio>
#include <cstring>
#include <type_traits>

// Optional facade. Legacy sketches keep using CodeLabFast4wd unchanged.
namespace codelab { namespace newmania {

enum class Motor : uint8_t { M1, M2, M3, M4 };
enum class Direction : uint8_t { Forward, Reverse };
enum class Axis : uint8_t { LeftX, LeftY, RightX, RightY };
enum class Button : uint8_t {
  X, Circle, Square, Triangle, L1, R1, L2, R2, Share, Options,
  L3, R3, Home, Up, Down, Left, Right
};
enum class ButtonState : uint8_t { Pressed, Held, Released };

// One cursor per Boolean Blockly block. Readers never consume shared input.
struct ButtonCursor { uint64_t event = 0; uint64_t epoch = 0; };

class Board {
 public:
  using Context = v2::ScriptContext;
  using Step = v2::StepResult;
  using Reset = void (*)();

  explicit Board(uint8_t limit = 100, fast4wd::MotorLayout layout = {})
      : robot_(limit, layout), gate_(robot_), scheduler_(gate_) {}
  Board(const Board&) = delete;
  Board& operator=(const Board&) = delete;

  void begin(bool blinkOnLoss = true, bool usesPs4 = false, uint32_t buttons = 0x1fcffU, uint8_t axes = 7) {
    if (begun_) return;
    Serial.begin(115200);
    robot_.configureBlockly(usesPs4, buttons, axes);
    robot_.begin(blinkOnLoss); // Existing wiring, frequency, startup and safety.
    begun_ = true;
  }

  // Called visibly by the student's once-per-RUN sequence. The receiver already
  // runs from begin()/update(), including before ARM. Never calls Wire.begin.
  bool connectPs4() {
    if (!begun_) return false;
    robot_.requirePs4();
    if (!ps4Requested_) { clearEdges(); ps4Requested_ = true; }
    return true; // Enables student reads; pairing/link availability is separate.
  }
  bool ps4Requested() const { return ps4Requested_; }
  bool connected() const { return begun_ && robot_.connected(); }

  bool registerProgram(uint32_t uid, v2::ScriptStep step, Reset reset = nullptr) {
    if (!uid || mainUid_ || !scheduler_.registerScript(uid, step)) return false;
    mainUid_ = uid;
    reset_ = reset;
    return true;
  }

  // Single cooperative main program. No new arbitration policy or event tasks.
  void update() {
    if (!begun_) return;
    robot_.beginLoop();
    const uint32_t now = millis();
    if (motionEpoch_ != robot_.motionEpoch()) {
      motionEpoch_ = robot_.motionEpoch();
      driveActive_ = driveTimed_ = false;
      scheduler_.cancelMotions(now);
      clearEdges();
    }
    scheduler_.safetyPhase(now);

    bool started = false;
    if (!started_ && mainUid_ && scheduler_.state() == v2::LifecycleState::READY) {
      started = scheduler_.startProgram(now);
      if (started) {
        started_ = true;
        resetRun();
        if (reset_) reset_(); // Before the first student statement, every RUN.
      }
    }
    if (running()) {
      // Count observed transitions independently of reader timing. Each Boolean
      // owns its cursor; no reader consumes another reader's transitions. Wait
      // invalidates all cursors and drops edges through its wake-up update.
      if (!started && scheduler_.scriptState(mainUid_) != v2::ScriptState::WAITING) {
        for (uint8_t b = 0; b < 17; ++b) {
          if (robot_.buttonEdge(b, true)) ++pressed_[b];
          if (robot_.buttonEdge(b, false)) ++released_[b];
        }
      }
      updateDriveTimer(now);
      applyDrive();
      scheduler_.tick(now);
      updateDriveTimer(now);
      if (running()) applyDrive();
    }
    if (!running()) { driveActive_ = driveTimed_ = false; clearEdges(); }
    robot_.endLoop(); // Poll/control/STOP/freshness watchdog remain serviced.
    serviceMessages();
  }

  bool running() const { return scheduler_.state() == v2::LifecycleState::RUN; }
  v2::LifecycleState state() const { return scheduler_.state(); }
  v2::FaultCode faultCode() const { return scheduler_.faultCode(); }
  uint32_t runGeneration() const { return scheduler_.runGeneration(); }
  uint32_t heartbeatAt() const { return scheduler_.heartbeatAt(); }
  static uint32_t repeatCount(double count) {
    return !std::isfinite(count) || count <= 0 ? 0 : count >= UINT32_MAX ? UINT32_MAX : static_cast<uint32_t>(count);
  }
  int serialAvailable() const { const int n = Serial.available(); return n < 0 ? 0 : n; }
  int serialRead() { return serialAvailable() > 0 ? Serial.read() : -1; }
  bool beginFor(ForLoop& loop, double& variable, Bounds bounds) {
    const bool valid = loop.begin(variable, bounds);
    if (!valid) message("Buoc lap phai khac 0 va cac gioi han phai huu han.");
    return valid;
  }
  double modulo(Pair values) {
    if (!std::isfinite(values.first) || !std::isfinite(values.second) || values.second == 0) {
      if (!arithmeticErrors_++) message("Khong the chia du voi so chia 0 hoac gia tri khong huu han.");
      return 0;
    }
    return std::fmod(values.first, values.second);
  }
  int32_t randomInt(Pair bounds) {
    int32_t low = Math::integer(bounds.first), high = Math::integer(bounds.second);
    if (low > high) { const auto tmp = low; low = high; high = tmp; }
    // One bounded PRNG step, no rejection loop in a cooperative callback.
    randomState_ ^= randomState_ << 13; randomState_ ^= randomState_ >> 17; randomState_ ^= randomState_ << 5;
    const uint64_t span = uint64_t(int64_t(high) - int64_t(low)) + 1;
    return static_cast<int32_t>(int64_t(low) + int64_t((uint64_t(randomState_) * span) >> 32));
  }

  bool button(Button which, ButtonState mode, ButtonCursor& cursor) const {
    const auto bit = static_cast<uint8_t>(which);
    if (bit >= 17 || !ps4Requested_ || !running() || !connected()) return false;
    if (mode == ButtonState::Held) return robot_.button(bit);
    if (mode != ButtonState::Pressed && mode != ButtonState::Released) return false;
    const auto event = mode == ButtonState::Pressed ? pressed_[bit] : released_[bit];
    if (cursor.epoch != edgeEpoch_) cursor = {0, edgeEpoch_};
    if (cursor.event == event) return false;
    ++cursor.event;
    return true;
  }
  bool held(Button which) const {
    const auto bit = static_cast<uint8_t>(which);
    return bit < 17 && ps4Requested_ && connected() && robot_.button(bit);
  }
  float axis(Axis which) const {
    const auto index = static_cast<uint8_t>(which);
    return begun_ && ps4Requested_ && index < 4 ? robot_.axis(index) : 0;
  }

  bool power(Motor motor, double percent) {
    return canCommand(motor) && scheduler_.motorWrite(port(motor), normalizePower(percent), millis());
  }
  bool spin(Motor motor, Direction direction, double percent) {
    if (direction != Direction::Forward && direction != Direction::Reverse) return false;
    const auto magnitude = normalizePower(std::isfinite(percent) && percent > 0 ? percent : 0);
    return power(motor, direction == Direction::Reverse ? -magnitude : magnitude);
  }
  uint32_t runFor(Motor motor, Direction direction, double percent, uint32_t ms) {
    if (!canCommand(motor) || ms < 1 || ms > 5000 ||
        (direction != Direction::Forward && direction != Direction::Reverse)) return 0;
    const auto magnitude = normalizePower(std::isfinite(percent) && percent > 0 ? percent : 0);
    return scheduler_.motorRunFor(port(motor), direction == Direction::Reverse ? -magnitude : magnitude, ms, millis());
  }
  bool stopMotor(Motor motor) { return power(motor, 0); }
  void stopAllMotors() {
    if (!running()) return;
    for (uint8_t m = 0; m < 4; ++m) stopMotor(static_cast<Motor>(m));
    stopDrive(); // Does not DISARM, matching the existing block.
  }
  void releaseMotor(Motor motor) {
    if (canCommand(motor)) robot_.releaseMotor(port(motor)); // Existing ownership semantics.
  }
  float motorPwm(Motor motor) const { return port(motor) < 4 ? robot_.motorPwm(port(motor)) : 0; }
  bool motionActive(uint32_t handle) const { return scheduler_.handleActive(handle); }

  void mecanum(double forward, double left, double counterclockwise) {
    if (!running() || !robot_.motionAllowed()) return;
    driveTimed_ = false;
    driveActive_ = true;
    drive_[0] = finitePercent(forward);
    drive_[1] = finitePercent(left);
    drive_[2] = finitePercent(counterclockwise);
  }
  void stopDrive() { mecanum(0, 0, 0); }
  bool driveFor(double forward, double left, double counterclockwise, uint32_t ms) {
    if (!running() || ms > 60000) return false;
    if (!ms) { stopDrive(); return true; }
    mecanum(forward, left, counterclockwise);
    driveTimed_ = true;
    driveDeadline_ = millis() + ms;
    return true;
  }

  Step wait(Context& ctx, uint32_t ms, uint16_t nextPc) {
    if (!validContext(ctx)) return Step::DONE;
    if (ms > 60000) { scheduler_.fault(v2::FaultCode::INLINE_LIMIT, millis()); return Step::DONE; }
    clearEdges();
    ctx.pc = nextPc;
    ctx.deadlineMs = millis() + ms;
    ctx.waitKind = v2::WaitKind::TIMER;
    return Step::WAIT;
  }
  Step waitMotion(Context& ctx, uint32_t handle, uint16_t nextPc) {
    if (!validContext(ctx)) return Step::DONE;
    if (!handle) { ctx.pc=nextPc; return Step::YIELD; } // Refused motor command is never queued for reconnect.
    clearEdges();
    ctx.pc = nextPc;
    ctx.handleId = handle;
    ctx.waitKind = v2::WaitKind::HANDLE;
    return Step::WAIT;
  }
  void stop() { scheduler_.stop(millis()); }

  // Bounded nonblocking messages. A future integration consumes popMessage();
  // these helpers never flush Serial or wait for a USB reader.
  bool message(const char* text) {
    return serialPrint(text, true);
  }
  bool serialPrint(const char* text, bool newline = true) {
    if (!text) return false;
    size_t n = 0;
    while (n < kMessageLength && text[n]) ++n;
    if (n == kMessageLength || messageCount_ == kMessages) { ++messageDrops_; return false; }
    std::memcpy(messages_[messageHead_], text, n + 1);
    messageNewline_[messageHead_] = newline;
    messageHead_ = (messageHead_ + 1) % kMessages;
    ++messageCount_;
    return true;
  }
  bool message(const Text& text) { return serialPrint(text, true); }
  bool serialPrint(const Text& text, bool newline = true) {
    if (!text.valid()) { ++messageDrops_; return false; }
    return serialPrint(text.data(), newline);
  }
  template<class Value> bool serialPrint(const Value& value, bool newline = true) {
    return serialPrint(Text::from(value), newline);
  }
  bool message(double number) {
    if (!std::isfinite(number)) { ++messageDrops_; return false; }
    char text[32]{};
    const int written = std::snprintf(text, sizeof(text), "%.6g", number);
    if (written <= 0 || size_t(written) >= sizeof(text)) { ++messageDrops_; return false; }
    return message(text);
  }
  template<class Number, typename std::enable_if<std::is_arithmetic<Number>::value, int>::type = 0>
  bool message(Number number) { return message(static_cast<double>(number)); }
  bool popMessage(char* out, size_t capacity) {
    if (!out || !capacity || !messageCount_) return false;
    const auto* text = messages_[messageTail_];
    size_t n = 0;
    while (text[n] && n + 1 < capacity) { out[n] = text[n]; ++n; }
    out[n] = '\0';
    messageTail_ = (messageTail_ + 1) % kMessages;
    messageOffset_ = 0;
    --messageCount_;
    return true;
  }
  uint32_t messageDrops() const { return messageDrops_; }

 private:
  static constexpr size_t kMessages = 8, kMessageLength = 128;
  static uint8_t port(Motor motor) { return static_cast<uint8_t>(motor); }
  static int16_t normalizePower(double n) {
    return !std::isfinite(n) ? 0 : static_cast<int16_t>(n < -100 ? -100 : n > 100 ? 100 : n);
  }
  static float finitePercent(double n) { return std::isfinite(n) ? static_cast<float>(n / 100.0) : 0; }
  bool canCommand(Motor motor) const {
    return port(motor) < 4 && running() && robot_.motionAllowed();
  }
  bool validContext(const Context& ctx) const {
    return running() && ctx.scriptUid == mainUid_ && ctx.runGeneration == runGeneration();
  }
  void resetRun() {
    driveActive_ = driveTimed_ = false;
    clearEdges();
    messageHead_ = messageTail_ = messageCount_ = 0;
    messageOffset_ = 0;
    messageDrops_ = 0;
    arithmeticErrors_ = 0;
    ps4Requested_ = false;
  }
  void clearEdges() {
    for (auto& value : pressed_) value = 0;
    for (auto& value : released_) value = 0;
    ++edgeEpoch_;
    if (!edgeEpoch_) ++edgeEpoch_;
  }
  void updateDriveTimer(uint32_t now) {
    if (driveTimed_ && static_cast<int32_t>(now - driveDeadline_) >= 0) stopDrive();
  }
  void applyDrive() { if (driveActive_ && robot_.motionAllowed()) robot_.move(drive_[0], drive_[1], drive_[2]); }
  void serviceMessages() {
    // Bounded work; never flush or wait for a USB reader. Keep safety in update().
    for (unsigned budget = 0; budget < 32 && messageCount_; ++budget) {
      const char next = messages_[messageTail_][messageOffset_];
      if (!next && !messageNewline_[messageTail_]) {
        messageTail_ = (messageTail_ + 1) % kMessages; --messageCount_; messageOffset_ = 0; continue;
      }
      if (Serial.availableForWrite() <= 0) break;
      if (Serial.write(static_cast<uint8_t>(next ? next : '\n')) != 1) break;
      if (next) ++messageOffset_;
      else { messageTail_ = (messageTail_ + 1) % kMessages; --messageCount_; messageOffset_ = 0; }
    }
  }

  fast4wd::Robot robot_;
  fast4wd::SchedulerGate gate_;
  v2::Scheduler scheduler_;
  uint32_t mainUid_ = 0, driveDeadline_ = 0, motionEpoch_ = 0;
  uint64_t edgeEpoch_ = 1;
  uint64_t pressed_[17]{}, released_[17]{};
  Reset reset_ = nullptr;
  bool begun_ = false, started_ = false, ps4Requested_ = false, driveActive_ = false, driveTimed_ = false;
  float drive_[3]{};
  char messages_[kMessages][kMessageLength]{};
  bool messageNewline_[kMessages]{};
  size_t messageHead_ = 0, messageTail_ = 0, messageCount_ = 0;
  size_t messageOffset_ = 0;
  uint32_t messageDrops_ = 0;
  uint32_t randomState_ = 0x6d2b79f5U, arithmeticErrors_ = 0;
};

} }

#include "CodeLabV2Scheduler.hpp"

#include <functional>
#include <cstring>

namespace codelab::v2 {

void MockMotorOutputGate::hardLock() {
  locked_ = true;
  for (auto& output : outputs_) output = {};
}

bool MockMotorOutputGate::unlock(uint32_t generation) {
  generation_ = generation;
  locked_ = false;
  return true;
}

bool MockMotorOutputGate::write(uint8_t motor, int16_t power, uint32_t generation, uint32_t handleId) {
  if (motor >= outputs_.size() || locked_ || generation != generation_) return false;
  outputs_[motor] = {power, generation, handleId};
  return true;
}

bool MockMotorOutputGate::stopIfOwned(uint8_t motor, uint32_t generation, uint32_t handleId) {
  if (motor >= outputs_.size()) return false;
  auto& out = outputs_[motor];
  if (out.generation != generation || out.handleId != handleId) return false;
  out.power = 0;
  out.handleId = 0;
  return true;
}

Scheduler::Scheduler(MotorOutputGate& gate) : gate_(gate) {}

bool Scheduler::registerScript(uint32_t id, ScriptStep step) {
  if (!step || find(id) || scriptCount_ == kMaxScripts) return false;
  auto& slot = slots_[scriptCount_++];
  slot.ctx.scriptUid = id;
  slot.step = step;
  slot.hat = HatKind::START;
  slot.state = ScriptState::INACTIVE;
  return true;
}

bool Scheduler::registerEventScript(uint32_t id, ScriptStep step, uint8_t button, Edge edge) {
  if (button >= 17 || !registerScript(id, step)) return false;
  auto* slot = find(id);
  slot->hat = HatKind::BUTTON_EDGE;
  slot->button = button;
  slot->edge = edge;
  return true;
}

bool Scheduler::startAuto(uint32_t nowMs, uint32_t maxRunMs) {
  if (state_ != LifecycleState::READY || maxRunMs == 0 || maxRunMs > 60'000) return false;
  ++runGeneration_;
  if (!runGeneration_) ++runGeneration_;
  state_ = LifecycleState::RUN;
  controllerMode_ = false;
  faultCode_ = FaultCode::NONE;
  autoDeadlineMs_ = nowMs + maxRunMs;
  heartbeatAt_ = nowMs;
  // Reset every continuation while retaining the registered stable script IDs.
  for (size_t i = 0; i < scriptCount_; ++i) {
    auto& s = slots_[i];
    const uint32_t id = s.ctx.scriptUid;
    s.ctx = {};
    s.ctx.scriptUid = id;
    s.ctx.runGeneration = runGeneration_;
    s.ctx.active = s.hat == HatKind::START;
    s.pending = false;
    s.state = s.hat == HatKind::START ? ScriptState::RUNNABLE : ScriptState::INACTIVE;
  }
  for (auto& h : handles_) h = {};
  cursor_ = 0;
  gate_.unlock(runGeneration_);
  record("start", nowMs, runGeneration_);
  return true;
}

bool Scheduler::startController(uint32_t nowMs) {
  if (state_ != LifecycleState::READY) return false;
  ++runGeneration_;
  if (!runGeneration_) ++runGeneration_;
  state_ = LifecycleState::RUN;
  controllerMode_ = true;
  faultCode_ = FaultCode::NONE;
  heartbeatAt_ = nowMs;
  for (size_t i = 0; i < scriptCount_; ++i) {
    auto& s = slots_[i];
    const uint32_t id = s.ctx.scriptUid;
    s.ctx = {};
    s.ctx.scriptUid = id;
    s.ctx.runGeneration = runGeneration_;
    s.ctx.active = s.hat == HatKind::START;
    s.pending = false;
    s.state = s.hat == HatKind::START ? ScriptState::RUNNABLE : ScriptState::INACTIVE;
  }
  for (auto& h : handles_) h = {};
  cursor_ = 0;
  gate_.unlock(runGeneration_);
  record("start", nowMs, runGeneration_);
  return true;
}

bool Scheduler::startProgram(uint32_t nowMs) {
  // Unlimited cooperative program; no controller input or ARM prerequisite.
  return startController(nowMs);
}

void Scheduler::cancelMotions(uint32_t nowMs) {
  gate_.hardLock();
  for (auto& h : handles_) if (h.state == HandleState::ACTIVE) h.state = HandleState::CANCELED;
  if (state_ == LifecycleState::RUN) gate_.unlock(runGeneration_);
  record("motors-canceled",nowMs);
}

void Scheduler::cancelAll(uint32_t nowMs) {
  gate_.hardLock();
  for (size_t i = 0; i < scriptCount_; ++i) {
    auto& s = slots_[i];
    s.pending = false;
    s.ctx.active = false;
    s.ctx.waitKind = WaitKind::NONE;
    s.state = ScriptState::CANCELED;
  }
  for (auto& h : handles_) if (h.state == HandleState::ACTIVE) h.state = HandleState::CANCELED;
  record("cancel", nowMs);
}

void Scheduler::stop(uint32_t nowMs) {
  if (state_ != LifecycleState::RUN) return;
  state_ = LifecycleState::READY; // STOP wins before cleanup and any stale write.
  ++runGeneration_;
  if (!runGeneration_) ++runGeneration_;
  cancelAll(nowMs);
  faultCode_ = FaultCode::NONE;
  record("stop", nowMs);
}

void Scheduler::fault(FaultCode code, uint32_t nowMs) {
  if (state_ == LifecycleState::FAULT) return;
  state_ = LifecycleState::FAULT;
  ++runGeneration_;
  if (!runGeneration_) ++runGeneration_;
  faultCode_ = code;
  cancelAll(nowMs);
  record("fault", nowMs, static_cast<uint32_t>(code));
}

bool Scheduler::clearFault() {
  if (state_ != LifecycleState::FAULT) return false;
  state_ = LifecycleState::READY;
  faultCode_ = FaultCode::NONE;
  controllerMode_ = false;
  return true;
}

void Scheduler::buttonEdge(uint8_t button, Edge edge, uint32_t nowMs) {
  if (button >= 17) return;
  ++ps4_.sequence;
  ps4_.pressed[button] = edge == Edge::PRESS;
  record(edge == Edge::PRESS ? "press" : "release", nowMs, button);
  if (state_ != LifecycleState::RUN) return;
  for (size_t i = 0; i < scriptCount_; ++i) {
    auto& s = slots_[i];
    if (s.hat != HatKind::BUTTON_EDGE || s.button != button ||
        s.state == ScriptState::DONE || s.state == ScriptState::CANCELED) continue;
    if (s.edge == edge) {
      s.pending = true;
      s.pendingSequence = ps4_.sequence;
    } else {
      // An opposite edge invalidates a queued token for this hat.
      s.pending = false;
      if (!s.ctx.active && s.state == ScriptState::WAITING) s.state = ScriptState::INACTIVE;
    }
    if (s.state == ScriptState::INACTIVE && s.pending) s.state = ScriptState::WAITING;
  }
}

bool Scheduler::tokenStillValid(const Slot& s) const {
  return s.pending && ps4_.pressed[s.button] == (s.edge == Edge::PRESS);
}

void Scheduler::record(const char* kind, uint32_t atMs, uint32_t value) {
  if (traceCount_ >= trace_.size()) { ++traceDrops_; return; }
  auto& event = trace_[traceCount_++];
  std::strncpy(event.kind, kind, sizeof(event.kind) - 1);
  event.atMs = atMs;
  event.value = value;
}

void Scheduler::safetyPhase(uint32_t nowMs) {
  if (state_ != LifecycleState::RUN) return;
  if (!controllerMode_ && static_cast<int32_t>(nowMs - autoDeadlineMs_) >= 0) {
    fault(FaultCode::AUTO_MAX_RUNTIME, nowMs);
    return;
  }
  if (static_cast<uint32_t>(nowMs - heartbeatAt_) > kHeartbeatTimeoutMs) fault(FaultCode::LOOP_STALL, nowMs);
}

void Scheduler::tick(uint32_t nowMs) {
  safetyPhase(nowMs);
  if (state_ != LifecycleState::RUN) return;
  updateMotions(nowMs);
  callbackOperations_ = 0;
  for (size_t i = 0; i < scriptCount_; ++i) slots_[i].operationsThisTick = 0;
  for (size_t dispatched = 0; dispatched < scriptCount_; ++dispatched) {
    const size_t index = cursor_++ % scriptCount_;
    auto& s = slots_[index];
    if (s.state == ScriptState::INACTIVE || s.state == ScriptState::DONE || s.state == ScriptState::CANCELED) continue;
    if (s.hat == HatKind::BUTTON_EDGE) {
      if (s.pending) {
        if (!tokenStillValid(s)) {
          s.pending = false;
          if (!s.ctx.active) s.state = ScriptState::INACTIVE;
          continue;
        }
        if (s.ctx.active) continue; // one pending token waits until this invocation completes
        const uint32_t id = s.ctx.scriptUid;
        s.ctx = {};
        s.ctx.scriptUid = id;
        s.ctx.runGeneration = runGeneration_;
        s.ctx.active = true;
        s.pending = false;
      } else if (!s.ctx.active) {
        continue;
      }
    }
    if (s.state == ScriptState::WAITING) {
      if (s.ctx.waitKind == WaitKind::TIMER && static_cast<int32_t>(nowMs - s.ctx.deadlineMs) < 0) continue;
      if (s.ctx.waitKind == WaitKind::HANDLE && !handleDone(s.ctx.handleId)) continue;
      if (s.ctx.waitKind == WaitKind::TIMER || s.ctx.waitKind == WaitKind::HANDLE) s.ctx.waitKind = WaitKind::NONE;
    }
    s.state = ScriptState::RUNNABLE;
    s.pending = false;
    s.ctx.active = true;
    const StepResult result = s.step(s.ctx, nowMs);
    if (result == StepResult::DONE) {
      if (s.hat == HatKind::BUTTON_EDGE) {
        const uint32_t id = s.ctx.scriptUid;
        s.ctx = {};
        s.ctx.scriptUid = id;
        s.ctx.runGeneration = runGeneration_;
        s.state = s.pending ? ScriptState::WAITING : ScriptState::INACTIVE;
      } else {
        s.state = ScriptState::DONE;
        s.ctx.active = false;
        s.ctx.waitKind = WaitKind::NONE;
      }
    } else if (result == StepResult::WAIT) {
      if (s.ctx.waitKind == WaitKind::NONE) {
        fault(FaultCode::INLINE_LIMIT, nowMs); // malformed callback contract fails closed
        return;
      }
      s.state = ScriptState::WAITING;
    } else {
      s.state = s.ctx.active ? (s.hat == HatKind::BUTTON_EDGE ? ScriptState::WAITING : ScriptState::RUNNABLE)
                             : (s.hat == HatKind::BUTTON_EDGE ? ScriptState::INACTIVE : ScriptState::RUNNABLE);
    }
    if (state_ != LifecycleState::RUN) return;
  }
  updateMotions(nowMs);
  heartbeatAt_ = nowMs; // only after the tick returns through all bounded callbacks
  record("heartbeat", nowMs);
  if (isIdle()) {
    state_ = LifecycleState::READY;
    ++runGeneration_;
    if (!runGeneration_) ++runGeneration_;
    cancelAll(nowMs);
    record("auto-done", nowMs);
  }
}

bool Scheduler::motorWrite(uint8_t motor, int16_t power, uint32_t nowMs) {
  (void)nowMs;
  if (state_ != LifecycleState::RUN) return false;
  // A new accepted write invalidates any previous timed-motion owner on channel.
  for (auto& h : handles_) if (h.state == HandleState::ACTIVE && h.motor == motor) h.state = HandleState::CANCELED;
  return gate_.write(motor, power, runGeneration_, 0);
}

bool Scheduler::accountOperations(ScriptContext& ctx, uint32_t count) {
  auto* slot = find(ctx.scriptUid);
  if (!slot || count > kOpsPerScriptTick || slot->operationsThisTick + count > kOpsPerScriptTick) return false;
  slot->operationsThisTick = static_cast<uint16_t>(slot->operationsThisTick + count);
  callbackOperations_ += count;
  totalOperations_ += count;
  if (slot->operationsThisTick > maxCallbackOperations_) maxCallbackOperations_ = slot->operationsThisTick;
  return true;
}

uint32_t Scheduler::motorRunFor(uint8_t motor, int16_t power, uint32_t durationMs, uint32_t nowMs) {
  if (state_ != LifecycleState::RUN || motor >= 6) return 0;
  MotionHandle* free = nullptr;
  for (auto& h : handles_) if (h.state != HandleState::ACTIVE) { free = &h; break; }
  if (!free) return 0;
  for (auto& h : handles_) if (h.state == HandleState::ACTIVE && h.motor == motor) h.state = HandleState::CANCELED;
  uint32_t id = nextHandleId_++;
  if (!id) id = nextHandleId_++;
  *free = {id, runGeneration_, nowMs + durationMs, motor, HandleState::ACTIVE};
  if (!gate_.write(motor, power, runGeneration_, id)) { free->state = HandleState::CANCELED; return 0; }
  return id;
}

bool Scheduler::handleDone(uint32_t id) const {
  const auto* h = findHandle(id);
  return !h || h->state == HandleState::COMPLETE || h->state == HandleState::CANCELED;
}

bool Scheduler::handleActive(uint32_t id) const {
  const auto* h = findHandle(id);
  return h && h->state == HandleState::ACTIVE;
}

bool Scheduler::isIdle() const {
  if (controllerMode_) {
    for (size_t i = 0; i < scriptCount_; ++i) if (slots_[i].hat == HatKind::BUTTON_EDGE) return false;
  }
  for (size_t i = 0; i < scriptCount_; ++i) {
    const auto& s = slots_[i];
    if (s.state == ScriptState::RUNNABLE || s.state == ScriptState::WAITING || s.pending) return false;
  }
  for (const auto& h : handles_) if (h.state == HandleState::ACTIVE) return false;
  return true;
}

ScriptState Scheduler::scriptState(uint32_t id) const {
  const auto* s = find(id);
  return s ? s->state : ScriptState::INACTIVE;
}

size_t Scheduler::pendingCount(uint32_t id) const {
  const auto* s = find(id);
  return s && s->pending ? 1 : 0;
}

Scheduler::Slot* Scheduler::find(uint32_t id) {
  for (size_t i = 0; i < scriptCount_; ++i) if (slots_[i].ctx.scriptUid == id) return &slots_[i];
  return nullptr;
}
const Scheduler::Slot* Scheduler::find(uint32_t id) const {
  for (size_t i = 0; i < scriptCount_; ++i) if (slots_[i].ctx.scriptUid == id) return &slots_[i];
  return nullptr;
}
Scheduler::MotionHandle* Scheduler::findHandle(uint32_t id) {
  for (auto& h : handles_) if (h.id == id) return &h;
  return nullptr;
}
const Scheduler::MotionHandle* Scheduler::findHandle(uint32_t id) const {
  for (const auto& h : handles_) if (h.id == id) return &h;
  return nullptr;
}

void Scheduler::updateMotions(uint32_t nowMs) {
  for (auto& h : handles_) {
    if (h.state != HandleState::ACTIVE || static_cast<int32_t>(nowMs - h.deadlineMs) < 0) continue;
    gate_.stopIfOwned(h.motor, h.ownerGeneration, h.id);
    h.state = HandleState::COMPLETE;
    record("motion-done", nowMs, h.id);
  }
}

InlineCheck validateInlineGraph(const std::vector<std::vector<uint8_t>>& calls,
                                uint32_t expandedOps, size_t frameBytes) {
  InlineCheck result{true, expandedOps, frameBytes, {}};
  if (expandedOps > Scheduler::kMaxExpandedOps || frameBytes > Scheduler::kMaxFrameBytes) {
    result.valid = false; result.error = "V2_PROC_INLINE_LIMIT"; return result;
  }
  std::vector<uint8_t> color(calls.size());
  std::function<bool(size_t)> visit = [&](size_t node) {
    color[node] = 1;
    for (uint8_t child : calls[node]) {
      if (child >= calls.size()) { result.error = "V2_PROC_UNKNOWN_TARGET"; return false; }
      if (color[child] == 1) { result.error = "V2_PROC_RECURSION"; return false; }
      if (color[child] == 0 && !visit(child)) return false;
    }
    color[node] = 2;
    return true;
  };
  for (size_t i = 0; i < calls.size(); ++i) if (!color[i] && !visit(i)) { result.valid = false; return result; }
  return result;
}

